#include "can_v_private.h"

void gpio_iface_rf_loop_toggle(void);

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Boolean can_v_rx (Can_V_Rx can_v_rx  , Can_Msg * can_msg , TskTimeout timeout)
{
  Rx_Q_Msg * rx_q_msg = (Rx_Q_Msg *) os_mbx_rcev (can_v_rx->obj.exec.q_rcev , timeout) ;

  if (rx_q_msg)
    {
      *can_msg = rx_q_msg->can_msg ;

      os_mbx_send (can_v_rx->obj.exec.q_free , (MbxMsg *) rx_q_msg) ;

      #if DBG_CAN == 1   
	    gpio_iface_rf_loop_toggle();
      #endif
      return TRUE ;
    }

  return FALSE ;
}

